import{circuitPair,sensorFigure}from './el2-figures.js?v=20261023-physicscomplete01';const f=(title,steps,render,note)=>({title,steps,render,note,duration:16});export const el2Films={
'el2-series':f('Trace a single series loop',['Read the6V source.','Add10Ω and20Ω in series.','The same0.2A passes both resistors.','Componentpd2V and4V add to6V.'],p=>circuitPair({topology:'series',moving:true,progress:p}),'Worked6V/10Ω/20Ω ideal constant-temperature circuit. Values represent a steady state, not a charging transient. Conventional-current marker motion is symbolic, not literal carrier speed, energy packets or calibrated counts. Replay restarts the view; actual experiment controls remain saved.'),
'el2-parallel':f('Split, rejoin and open one branch',['Both closed branches share6V.','10Ω draws0.6A;20Ω draws0.3A.','The total source current is0.9A.','Opening branch2 leaves0.6A in branch1.'],p=>circuitPair({topology:'parallel',R2:p<.75?20:null,moving:true,progress:p}),'Ideal fixed6V source; branch2 opens at the last stage as a counterfactual. The gap is visible and its current becomes zero; no full-sourcepd is assigned across its isolated resistor. Each state is a steady snapshot, not an inductive switching transient. Tracers are qualitative; displayed branch currents conserve charge. Not numerical parallel equivalent-resistance teaching.'),
'el2-combinations':f('Compare the same resistors in two arrangements',['A series pair has one path.','Its source current is0.2A at6V.','A parallel pair provides two paths.','The branch currents add to0.9A.'],p=>circuitPair({topology:p<.5?'series':'parallel',R2:20,moving:true,progress:p}),'Worked10Ω/20Ω examples at6V. A deliberate midpoint cut compares two separate wired states; it is not a demonstration of rewiring a live circuit. Supply-off checks/current limits and real measurements require school supervision. Parallel equivalent-resistance formula is not required.'),
'el2-thermistor':f('Sense temperature and choose heating',['The imposed temperature begins at20°C.','As it warms, sensor resistance falls.','The chosen controller turns heating off at40°C.','Cooling below40°C turns the chosen output on again.'],p=>sensorFigure({kind:'thermistor',movie:true,progress:p}),'Original imposed20→60→20°C trajectory, constant2V measurement and R=1000/[1+0.04(T−20)]. This is a toy curve, not a required equation, device calibration or dynamic thermostat feedback simulation. Output ON below40°C is a chosen ideal rule; controller hardware/power supply omitted. Time and repeated reset are symbolic.'),
'el2-ldr':f('Sense light and switch a separate lamp',['The imposed light index begins dark.','More light lowers sensor resistance.','The chosen controller turns the lamp off in bright conditions.','Returning to darkness switches it on.'],p=>sensorFigure({kind:'ldr',movie:true,progress:p}),'Original imposed light-index0→100→0 and R=10000/(1+0.09L) at2V. Index is not lux; this is not a device calibration. Lamp ON below50 is a chosen controller rule with separate power/control stage represented as a block. The lamp does not cause this prescribed light trajectory; timing symbolic, no hysteresis or self-heating model.')};
